using System.Text.Json;
using Satori.Core;

namespace Satori.Numerics.Tests;

/// <summary>
/// DW06.2: the GGML Q6_K super-block decoder and dot product, checked against an independent FP64
/// reference generated by <c>tools/q6k_reference.py</c> from the pinned ggml layout.
/// </summary>
public sealed class Q6KCodecTests
{
    private static readonly JsonElement Fixture = JsonDocument.Parse(
        File.ReadAllText(Path.Combine(GgufTests.Root, "fixtures/operators/q6k-v1.json"))).RootElement;

    private static byte[] Hex(string value) => Convert.FromHexString(value);

    [Fact]
    public void DecodedWeightsMatchReference()
    {
        foreach (var test in Fixture.GetProperty("cases").EnumerateArray())
        {
            string name = test.GetProperty("name").GetString()!;
            byte[] block = Hex(test.GetProperty("block_hex").GetString()!);
            float[] weights = new float[Q6KCodec.ElementsPerBlock];
            Q6KCodec.DecodeBlock(block, weights);
            int index = 0;
            foreach (var expected in test.GetProperty("weights").EnumerateArray())
            {
                double reference = expected.GetDouble();
                Assert.True(Math.Abs(weights[index] - reference) <= 1e-3 + 1e-4 * Math.Abs(reference),
                    $"{name} weight[{index}]: {weights[index]} vs {reference}");
                index++;
            }
            Assert.Equal(Q6KCodec.ElementsPerBlock, index);
        }
    }

    [Fact]
    public void DotMatchesReference()
    {
        foreach (var test in Fixture.GetProperty("cases").EnumerateArray())
        {
            string name = test.GetProperty("name").GetString()!;
            byte[] payload = Hex(test.GetProperty("block_hex").GetString()!);
            float[] input = test.GetProperty("input").EnumerateArray().Select(v => v.GetSingle()).ToArray();
            var shape = new QuantizedMatrixShape(1, Q6KCodec.ElementsPerBlock, BlockQuantization.Q6_K);
            Assert.Equal(payload.Length, shape.ByteLength);
            float[] output = new float[1];
            QuantizedMatVec.ExecuteScalar(payload, shape, input, output);
            double reference = test.GetProperty("dot").GetDouble();
            Assert.True(Math.Abs(output[0] - reference) <= 1e-2 + 1e-4 * Math.Abs(reference),
                $"{name} dot: {output[0]} vs {reference}");
        }
    }

    [Fact]
    public void NonFiniteSuperBlockScaleIsRejected()
    {
        // d = +Infinity (FP16 0x7C00) at offset 208, everything else zero.
        byte[] payload = new byte[Q6KCodec.BytesPerBlock];
        payload[208] = 0x00;
        payload[209] = 0x7C;
        var shape = new QuantizedMatrixShape(1, Q6KCodec.ElementsPerBlock, BlockQuantization.Q6_K);
        Assert.Throws<InvalidDataException>(() => new QuantizedMatrix(payload, shape));
    }

    [Fact]
    public void ShapeRejectsRowsThatAreNotWholeSuperBlocks()
    {
        Assert.Throws<ArgumentOutOfRangeException>(() =>
            new QuantizedMatrixShape(1, 128, BlockQuantization.Q6_K));
        Assert.Equal(Q6KCodec.BytesPerBlock, new QuantizedMatrixShape(1, 256, BlockQuantization.Q6_K).ByteLength);
    }
}
